add(kp,"在进程的五状态模型中，增加了（）状态。","创建和终止",["挂起和激活","等待和就绪","运行和阻塞"],"五状态模型在三种基本状态（就绪、运行、阻塞）的基础上增加了创建（New）和终止（Terminated）状态。")
add(kp,"在进程的七状态模型中，增加了（）状态。","就绪挂起和阻塞挂起",["运行","就绪","阻塞"],"七状态模型在五状态基础上增加了就绪挂起（Ready Suspend）和阻塞挂起（Blocked Suspend）状态。","中等")
add(kp,"进程“挂起”状态的主要目的是（）。","将进程从内存中换出到外存，释放内存空间",["终止进程","创建进程","调度进程"],"挂起操作将进程从内存移到外存（磁盘交换区），以释放内存空间供其他进程使用。","中等")
