add(kp,"线程调度的“公平性”是指（）。","所有线程都有合理的机会获得CPU",["所有线程获得相同的CPU时间","所有线程立即运行","所有线程同时运行"],"公平性确保每个就绪线程都能获得合理的CPU执行机会，避免饥饿。")
add(kp,"在线程调度中，“亲和性”（Affinity）是指（）。","尽量将线程调度到它之前运行过的CPU上",["线程之间的亲属关系","线程不能迁移","线程必须运行在指定CPU"],"CPU亲和性利用缓存热点，将线程调度到同一CPU上以提高缓存命中率。","中等")
add(kp,"以下关于Linux CFS调度器的描述，正确的是（）。","CFS采用红黑树来管理就绪线程",["CFS使用固定优先级","CFS不支持抢占","CFS是一种实时调度器"],"CFS（Completely Fair Scheduler）使用红黑树维护就绪线程，根据虚拟运行时间进行调度。","中等")
add(kp,"在多CPU系统中，线程调度的“负载均衡”是指（）。","将线程均匀分配到各个CPU上",["将所有线程放在一个CPU上","只使用部分CPU","减少线程数量"],"负载均衡确保所有CPU的负载大致均匀，避免某些CPU过载而其他空闲。")
add(kp,"以下关于实时线程调度的描述，正确的是（）。","实时线程需要保证在截止时间前完成",["实时线程没有时间限制","实时线程优先级最低","实时线程不使用抢占"],"实时调度需要保证关键任务在规定的时间截止前完成，具有时间确定性。","中等")
add(kp,"线程调度的“时间片”大小影响（）。","系统响应时间和CPU利用率",["线程数量","线程大小","线程优先级"],"时间片太小→频繁切换→开销大；时间片太大→响应时间变长→交互性差。","中等")
add(kp,"以下关于“多处理器调度”的描述，正确的是（）。","需要考虑线程在不同CPU之间的负载均衡",["与单处理器调度完全相同","不需要负载均衡","只能使用一个CPU"],"多处理器调度除了单处理器的考虑外，还需要处理负载均衡和CPU亲和性等问题。")
add(kp,"线程调度中，I/O密集型线程和CPU密集型线程的区别是（）。","I/O密集型线程频繁进行I/O操作，CPU密集型线程长期占用CPU",["两者完全相同","I/O密集型线程占用CPU更多","CPU密集型线程I/O更多"],"I/O密集型线程频繁等待I/O，CPU密集型线程需要长时间CPU计算。","中等")
add(kp,"在线程调度中，优先级反转问题是指（）。","低优先级线程占用资源导致高优先级线程等待",["高优先级线程占用资源","线程优先级不变","线程不能被调度"],"优先级反转：低优先级线程持有高优先级线程需要的资源，导致高优先级被低优先级间接阻塞。","中等")
add(kp,"解决优先级反转问题的方法是（）。","优先级继承",["降低优先级","增加线程数","使用FCFS"],"优先级继承（Priority Inheritance）临时提升持有资源的低优先级线程的优先级，使其尽快释放资源。","中等")
add(kp,"以下关于线程调度策略选择的描述，正确的是（）。","通用系统通常采用多级反馈队列",["所有系统使用FCFS","所有系统使用SJF","实时系统使用FCFS"],"通用操作系统（如Windows、Linux）通常使用多级反馈队列等混合调度策略。","中等")
add(kp,"线程的“上下文切换”由（）触发。","时间片到期、线程阻塞、高优先级线程抢占等",["仅时间片到期","线程主动请求","用户手动触发"],"线程上下文切换由多种事件触发：时间片用完、线程阻塞等待、中断唤醒高优先级线程等。")
add(kp,"线程调度中，“长程调度”和“短程调度”的区别在于（）。","长程调度决定哪些作业进入系统，短程调度决定CPU分配",["两者完全相同","长程调度分配CPU","短程调度决定作业"],"长程调度（作业调度）控制进入系统的作业数；短程调度（CPU调度）频繁执行，分配CPU给线程。","中等")
add(kp,"对于交互式系统，线程调度最重要的是（）。","响应时间短",["吞吐量高","CPU利用率高","公平性"],"交互式系统（如桌面系统）强调快速响应用户输入，响应时间是关键指标。")
add(kp,"对于批处理系统，线程调度最重要的是（）。","吞吐量高",["响应时间短","公平性","交互性好"],"批处理系统关注单位时间内完成的作业数量（吞吐量），不关心即时响应。")
add(kp,"线程调度算法中，“最高响应比优先”（HRRN）的响应比计算公式是（）。","响应比 = (等待时间 + 服务时间) / 服务时间",["响应比 = 等待时间 / 服务时间","响应比 = 服务时间 / 等待时间","响应比 = 等待时间 × 服务时间"],"HRRN（Highest Response Ratio Next）综合考虑等待时间和服务时间，长等待的线程优先。","中等")
add(kp,"在抢占式调度中，当前运行线程被抢占后进入（）。","就绪状态",["阻塞状态","终止状态","创建状态"],"被抢占的线程从运行状态回到就绪状态，等待再次被调度。")
add(kp,"线程调度中，“吞吐量”是指（）。","单位时间内完成的线程数量",["线程的响应时间","线程的等待时间","CPU的利用率"],"吞吐量（Throughput）是单位时间内系统完成的任务数量，是批处理系统的重要指标。")
add(kp,"在实时系统中，线程调度的关键是（）。","保证任务在截止时间前完成",["提高平均响应时间","最大化吞吐量","减少线程数量"],"实时系统（如工业控制）的时间确定性至关重要，必须在规定时限内完成任务。","中等")
