add(kp,"以下关于多核处理器的优势，描述正确的是（）。","提高并行处理能力，降低功耗",["只能运行一个程序","增加功耗","降低性能"],"多核处理器可以在较低频率下并行处理更多任务，提高性能的同时控制功耗。")
add(kp,"多核系统中，以下哪种方式可以充分利用多核（）。","多线程编程",["单线程编程","单进程编程","批处理"],"多线程程序可以将不同线程分配到不同核心并行执行，充分利用多核优势。")
add(kp,"以下关于多线程和多核的关系，描述正确的是（）。","多核CPU可以真正并行执行多个线程",["多核CPU只能并发执行线程","多核和多线程无关","多核只能运行一个线程"],"单核CPU只能并发（交替执行），多核CPU可以实现真正的并行（同时执行）。")
add(kp,"Amdahl定律表明，程序的加速比受限于（）。","程序中不可并行化的部分",["CPU核心数量","内存大小","硬盘速度"],"Amdahl定律：加速比S=1/((1-P)+P/N)，其中P是可并行化比例，(1-P)是串行部分，串行部分成为瓶颈。","中等")
add(kp,"超线程技术（Hyper-Threading）是指（）。","一个物理核心模拟出两个逻辑核心",["一个芯片上有多个物理核心","增加CPU频率","增加内存容量"],"超线程技术在一个物理核心上模拟两个逻辑处理器，提高CPU资源的利用率。","中等")
add(kp,"超线程技术的原理是（）。","利用CPU执行单元的空闲时间处理另一个线程",["增加CPU核心数量","提高CPU频率","增加缓存"],"超线程使一个核心同时维护两个线程的上下文，当一个线程等待时立即切换到另一个线程。")
add(kp,"以下关于并行和并发的区别，正确的是（）。","并行是同时执行，并发是交替执行",["并行和并发完全相同","并发是同时执行","并行是交替执行"],"并行（Parallel）是多核同时运行多个任务；并发（Concurrent）是单核快速交替执行多个任务。","中等")
add(kp,"在多核系统中，线程的调度需要考虑（）。","负载均衡和CPU亲和性",["仅负载均衡","仅CPU亲和性","不需要特殊考虑"],"多核调度需要考虑将线程均匀分配到各核心（负载均衡），同时尽量保持在同一核心（亲和性）。")
add(kp,"以下关于多核编程的挑战，描述正确的是（）。","需要处理数据竞争、负载均衡等问题",["和单核编程完全相同","不需要同步","不能使用线程"],"多核编程面临数据竞争、死锁、负载不均衡、缓存一致性等挑战。","中等")
add(kp,"CPU亲和性（CPU Affinity）在多核系统中的好处是（）。","提高缓存命中率，减少缓存失效",["增加CPU负载","降低性能","增加功耗"],"将线程绑定到特定核心可以提高L1/L2缓存命中率，因为线程的数据可能仍在缓存中。","中等")
add(kp,"在多核系统中，伪共享（False Sharing）是指（）。","不同核心的线程修改同一缓存行中的不同变量",["线程共享虚假数据","缓存完全失效","线程间错误通信"],"伪共享导致缓存行在不同核心间频繁传输，严重影响多核性能。","中等")
add(kp,"以下关于多核时代编程方式的改变，描述正确的是（）。","更多地使用多线程和并行编程",["继续使用单线程","不使用并发","减少线程使用"],"多核时代要求程序利用多线程和并行编程来充分利用硬件资源。")
add(kp,"在现代操作系统中，以下哪种调度策略适用于多核环境（）。","全局调度和分区调度",["仅FCFS","仅SJF","单队列调度"],"多核调度有全局调度（所有核心共享线程池）和分区调度（每个核心有单独队列）两种策略。")
add(kp,"多核环境下，读写锁（Read-Write Lock）的优势是（）。","允许多个读者同时访问，提高并行度",["只允许一个读者访问","和互斥锁完全相同","不适合多核"],"读写锁允许多个读者同时读取共享资源（无修改），在多核环境下显著提高读密集型任务的并行度。","中等")
add(kp,"以下关于超线程的描述，正确的是（）。","超线程使一个核心可以交替执行两个线程",["超线程使CPU频率翻倍","超线程增加物理核心数","超线程不影响性能"],"超线程通过复制架构状态让一个核心同时维护两个硬件线程，减少CPU空闲时间。")
add(kp,"多核系统中，以下哪种方式可以减少锁竞争（）。","细粒度锁和无锁数据结构",["使用更大的锁","使用全局锁","增加锁的持有时间"],"细粒度锁（减小锁的范围）和无锁数据结构可以减少线程间的锁竞争，提高多核并行度。","中等")
