add(kp,"在现代多核操作系统中，“SMP”指的是（）。","对称多处理（各核心平等访问内存和I/O）",["非对称多处理","单一处理","虚拟处理"],"SMP（Symmetric Multi-Processing）系统中所有CPU核心对等地访问内存和I/O设备。","中等")
add(kp,"以下关于多核环境下的缓存一致性，描述正确的是（）。","MESI等协议确保各核心缓存中数据的一致性",["不需要保持一致性","各核心缓存完全独立","只有单一协议"],"MESI（Modified/Exclusive/Shared/Invalid）等缓存一致性协议确保多核共享数据的一致性。","中等")
add(kp,"多核编程中，“任务并行”和“数据并行”的区别是（）。","任务并行是将不同任务分配给不同核心，数据并行是将数据分片后并行处理",["两者完全相同","数据并行比任务并行简单","多核不支持数据并行"],"任务并行（Task Parallelism）分解不同功能；数据并行（Data Parallelism）将数据分块同时处理。","中等")
add(kp,"以下关于多核系统下线程数量的选择，描述正确的是（）。","线程数应接近CPU核心数（CPU密集型），可以更多（I/O密集型）",["线程数越多越好","固定使用一个线程","线程数等于进程数"],"CPU密集型任务线程数≈核心数最合适；I/O密集型任务可以更多线程以隐藏等待时间。")
add(kp,"以下关于多核时代的锁策略，描述错误的是（）。","全局锁在多核环境下性能最好",["细粒度锁可以减少竞争","读写锁适合读多写少场景","无锁编程可以避免锁开销"],"全局锁在多核环境下会成为严重的性能瓶颈，应尽可能使用细粒度锁或并发数据结构。","中等")
add(kp,"NUMA架构中，每个CPU有（）。","自己本地内存，访问本地内存更快",["共享所有内存，访问速度相同","没有内存","只有一个CPU"],"NUMA（Non-Uniform Memory Access）中每个CPU有自己的本地内存，访问远端内存速度较慢。","中等")
add(kp,"在现代多核处理器中，“SIMD”指令指的是（）。","单指令多数据（一条指令同时处理多组数据）",["多指令单数据","单指令单数据","多指令多数据"],"SIMD（Single Instruction Multiple Data）可以在一个指令周期内对多个数据执行相同操作，提高数据并行度。","中等")
add(kp,"以下关于多核编程中的“屏障”（Barrier），描述正确的是（）。","屏障使所有线程到达同一点后才能继续",["屏障阻止线程运行","屏障是一种锁","屏障只能用于单线程"],"屏障（Barrier）同步是一种同步机制，所有参与线程必须都到达屏障点后才能一起继续执行。","中等")
add(kp,"在多核环境中，以下哪种做法有助于提高性能（）。","减少线程间的数据共享和同步",["增加全局锁的使用","让所有线程共享单一变量","不使用缓存"],"减少线程间的数据共享和同步可以减少锁竞争和缓存一致性开销，提高多核性能。")
add(kp,"以下关于“线程过载”（Over-subscription）在多核系统中的描述，正确的是（）。","线程数远多于核心数时，频繁上下文切换降低性能",["线程过载提高性能","线程过载不影响性能","线程数应无限多"],"线程数远超核心数时，频繁的上下文切换和资源竞争会导致性能下降。")
add(kp,"在多核系统中，“无锁（Lock-Free）编程”的优势是（）。","避免死锁和优先级反转，提高并发度",["需要更多锁","降低并发度","增加死锁风险"],"无锁编程使用CAS等原子操作替代锁，可以避免死锁、优先级反转等锁相关问题。","中等")
add(kp,"以下关于多核编程中“条件变量”的使用，描述正确的是（）。","条件变量用于线程间的事件通知和等待",["条件变量是一种锁","条件变量用于文件操作","只能用于单核"],"条件变量（Condition Variable）允许线程等待特定条件成立，通常与互斥锁配合使用。")
add(kp,"在多核系统中，以下哪种情况容易出现“死锁”（）。","线程互相等待对方持有的资源",["线程独立运行","线程数量较少","使用无锁编程"],"多线程环境中，多个线程相互等待对方释放资源时，会形成循环等待导致死锁。","中等")
